WITH last_agent_events AS (SELECT COALESCE(GET_JSON_OBJECT(metadata, event_data.WorkerSid), GET_JSON_OBJECT(metadata, event_data.TaskAttributes.worker_sid)) AS id_agent, MAX(GET_JSON_OBJECT(metadata, event_data.Sid)) AS id_last_event, MIN(ts_created_local) AS ts_first_event, MAX(ts_created_local) AS ts_last_event, year, month, day FROM datalake_bigfone_events.events WHERE provider = 'twilio' AND (GET_JSON_OBJECT(metadata, event_data.WorkflowName) = 'Assign to Anyone' OR GET_JSON_OBJECT(metadata, event_data.WorkflowName) = 'Assign to Flex') AND NOT GET_JSON_OBJECT(metadata, event_data.WorkerAttributes) IS NULL AND year = STRUCT(year AS year) AND month = STRUCT(month AS month) AND day = STRUCT(day AS day) GROUP BY 1, 5, 6, 7) SELECT lae.id_agent, GET_JSON_OBJECT(cfe.metadata, event_data.WorkerAttributes.email) AS email, GET_JSON_OBJECT(cfe.metadata, event_data.WorkerAttributes.full_name) AS full_name, GET_JSON_OBJECT(cfe.metadata, event_data.WorkerAttributes.location) AS location, GET_JSON_OBJECT(cfe.metadata, event_data.WorkerAttributes.routing.skills) AS skills, lae.ts_first_event, lae.ts_last_event, lae.year, lae.month, lae.day FROM datalake_bigfone_events.events AS cfe INNER JOIN last_agent_events AS lae ON GET_JSON_OBJECT(cfe.metadata, event_data.Sid) = lae.id_last_event WHERE cfe.provider = 'twilio' AND (GET_JSON_OBJECT(metadata, event_data.WorkflowName) = 'Assign to Anyone' OR GET_JSON_OBJECT(metadata, event_data.WorkflowName) = 'Assign to Flex') AND cfe.year = STRUCT(year AS year) AND cfe.month = STRUCT(month AS month) AND cfe.day = STRUCT(day AS day)